import json
import os
import socket
import subprocess
import time
from pathlib import Path

import docker
import httpx
import yaml

import settings

ROLE_LABEL = "inference-stack.role"
MODEL_LABEL = "inference-stack.model"
PORT = 8000


def _docker() -> docker.DockerClient:
    return docker.from_env()


def _model_servers() -> list:
    return _docker().containers.list(all=True, filters={"label": f"{ROLE_LABEL}=model-server", "network": settings.DOCKER_NETWORK})


def _address(container) -> str:
    container.reload()
    return container.attrs["NetworkSettings"]["Networks"][settings.DOCKER_NETWORK]["IPAddress"]


def _write_atomically(filename: str, content: str) -> None:
    path = os.path.join(settings.STATE_DIR, filename)
    os.makedirs(settings.STATE_DIR, exist_ok=True)
    with open(f"{path}.tmp", "w") as file:
        file.write(content)
    os.replace(f"{path}.tmp", path)


def publish_endpoints() -> None:
    """Tell the llm-d router and Prometheus which model servers exist."""
    servers = [c for c in _model_servers() if c.status == "running"]
    endpoints = [{"name": c.name, "address": _address(c), "port": str(PORT)} for c in servers]
    targets = [
        {"targets": [f"{e['address']}:{PORT}"], "labels": {"pod": e["name"], "namespace": "compose"}}
        for e in endpoints
    ]
    _write_atomically("endpoints.yaml", yaml.safe_dump({"endpoints": endpoints}))
    _write_atomically("model-servers.json", json.dumps(targets))


def has_gpu() -> bool:
    return "nvidia" in _docker().info().get("Runtimes", {})


def running_model() -> dict | None:
    servers = _model_servers()
    if not servers:
        return None
    return {
        "served_model": servers[0].labels[MODEL_LABEL],
        "replicas": len(servers),
        "ready": sum(_is_ready(c) for c in servers),
        "gpus_per_replica": int(servers[0].labels.get("inference-stack.gpus", "1")),
        "context": int(servers[0].labels.get("inference-stack.context", "4096")),
        "simulate": servers[0].labels.get("inference-stack.simulate") == "true",
    }


def _is_ready(container) -> bool:
    try:
        return httpx.get(f"http://{_address(container)}:{PORT}/health", timeout=2).status_code == 200
    except (httpx.HTTPError, KeyError, docker.errors.NotFound):
        return False


def remove_model_servers() -> None:
    for container in _model_servers():
        container.remove(force=True)
    publish_endpoints()


def pull_image(simulate: bool) -> None:
    """Download the model server image, raising the registry's own error if it fails."""
    image = settings.SIMULATOR_IMAGE if simulate else settings.VLLM_IMAGE
    if _docker().images.list(name=image):
        return
    for event in _docker().api.pull(image, stream=True, decode=True):
        if "error" in event:
            raise RuntimeError("Could not download the model server image. Check the image tag and registry access, then retry.")


def start_model_servers(served_model: str, replicas: int, simulate: bool, gpus: int = 1, context: int = 4096) -> None:
    remove_model_servers()
    for index in range(replicas):
        options = _simulator_options(served_model) if simulate else _vllm_options(served_model, index * gpus, gpus, context)
        _docker().containers.run(
            name=f"vllm-{index}",
            detach=True,
            network=settings.DOCKER_NETWORK,
            labels={ROLE_LABEL: "model-server", MODEL_LABEL: served_model, "inference-stack.gpus": str(gpus),
                    "inference-stack.context": str(context), "inference-stack.simulate": str(simulate).lower()},
            restart_policy={"Name": "unless-stopped"},
            **options,
        )


def _simulator_options(served_model: str) -> dict:
    return {
        "image": settings.SIMULATOR_IMAGE,
        "command": ["--model", served_model, "--port", str(PORT)],
    }


def _vllm_options(served_model: str, gpu_index: int, gpus: int = 1, context: int = 4096) -> dict:
    return {
        "image": settings.VLLM_IMAGE,
        "entrypoint": "vllm",
        "command": ["serve", served_model, "--port", str(PORT), "--tensor-parallel-size", str(gpus), "--max-model-len", str(context)],
        "environment": {"HUGGING_FACE_HUB_TOKEN": [REDACTED]},
        "volumes": {"inference-stack-huggingface": {"bind": "/root/.cache/huggingface", "mode": "rw"}},
        "shm_size": "8g",
        "device_requests": [docker.types.DeviceRequest(device_ids=[str(n) for n in range(gpu_index, gpu_index + gpus)], capabilities=[["gpu"]])],
    }


def wait_until_ready(timeout_seconds: int = 3600) -> None:
    deadline = time.monotonic() + timeout_seconds
    while time.monotonic() < deadline:
        servers = _model_servers()
        if any(c.status == "exited" for c in servers):
            raise RuntimeError("A model server exited. Run `docker logs vllm-0` to see why.")
        if servers and all(_is_ready(c) for c in servers):
            return
        time.sleep(2)
    raise RuntimeError("Model servers did not become ready in time.")


def gpu_inventory() -> dict:
    """Probe the Docker host, including when the launcher itself has no GPU devices."""
    command = ["nvidia-smi", "--query-gpu=name,memory.total,memory.used", "--format=csv,noheader,nounits"]
    probe = None
    try:
        if not has_gpu():
            return {"count": 0, "devices": [], "error": "No NVIDIA runtime detected. Install the NVIDIA Container Toolkit to serve models."}
        try:
            own_image = _docker().containers.get(socket.gethostname()).image.id
        except docker.errors.NotFound:
            output = subprocess.run(command, capture_output=True, text=True, timeout=10, check=True).stdout
        else:
            probe = _docker().containers.run(own_image, command, entrypoint="", detach=True,
                network_disabled=True, environment={"NVIDIA_DRIVER_CAPABILITIES": "utility"},
                device_requests=[docker.types.DeviceRequest(count=-1, capabilities=[["gpu"]])])
            if probe.wait(timeout=15)["StatusCode"] != 0:
                raise RuntimeError("GPU probe failed")
            output = probe.logs().decode()
        devices = []
        for line in output.strip().splitlines():
            name, memory, used = line.rsplit(",", 2)
            devices.append({"name": name.strip(), "memory_gb": round(float(memory) / 1024, 1),
                            "used_gb": round(float(used) / 1024, 1), "count": 1, "available": 1})
        return {"count": len(devices), "devices": devices, "error": ""}
    except Exception:
        return {"count": None, "devices": [], "error": "Could not inspect GPU capacity. Check Docker and the NVIDIA driver, then retry."}
    finally:
        if probe:
            try:
                probe.remove(force=True)
            except docker.errors.DockerException:
                pass


def routing_config() -> dict:
    path = Path(settings.STATE_DIR) / "epp-config.yaml"
    if not path.exists():
        _write_atomically("epp-config.yaml", Path(settings.ROUTING_CONFIG).read_text())
    return yaml.safe_load(path.read_text())


def save_routing(config: dict) -> None:
    _write_atomically("epp-config.yaml", yaml.safe_dump(config))
    containers = _docker().containers.list(filters={"label": "com.docker.compose.service=epp", "network": settings.DOCKER_NETWORK})
    if len(containers) != 1:
        raise RuntimeError("Could not locate the llm-d router. Check Docker Compose, then retry.")
    containers[0].restart(timeout=10)

#!/usr/bin/env python3
"""Install the AWS controller or a GPU worker. No models are installed."""

import base64
import datetime
import hashlib
import json
import os
from pathlib import Path
import re
import secrets
import shutil
import subprocess
import tarfile
import tempfile
import time
import urllib.error
import urllib.request
from urllib.parse import quote


ROOT = Path('/opt/inference-stack')


def run(*args):
    result = subprocess.run(args, capture_output=True, text=True, timeout=1800)
    if result.returncode:
        # Command output may contain credentials or deployment addresses.
        raise RuntimeError(f'{args[0]} failed; inspect the installation on this machine.')
    return result.stdout


def aws(*args):
    return json.loads(run('aws', *args, '--output', 'json'))


def write(path, content, mode=0o600):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    descriptor = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, mode)
    with os.fdopen(descriptor, 'w') as file:
        file.write(content)
    path.chmod(mode)


def download(url):
    with urllib.request.urlopen(url, timeout=120) as response:
        return response.read()


def install_bundle(version):
    if ROOT.exists():
        if (ROOT / 'VERSION').read_text().strip() != version:
            raise RuntimeError('Existing installation has a different version; preserve it and use the upgrade guide.')
        return
    release = f'https://github.com/BerriAI/inference-stack/releases/download/v{version}'
    filename = f'inference-stack-{version}.tar.gz'
    checksums = dict(line.split()[::-1] for line in download(f'{release}/SHA256SUMS').decode().splitlines())
    archive = download(f'{release}/{filename}')
    if hashlib.sha256(archive).hexdigest() != checksums.get(filename):
        raise RuntimeError('Release checksum did not match.')
    with tempfile.TemporaryDirectory() as directory:
        archive_path = Path(directory) / filename
        archive_path.write_bytes(archive)
        with tarfile.open(archive_path) as tar:
            for member in tar.getmembers():
                path = Path(member.name)
                if path.is_absolute() or '..' in path.parts or not (member.isfile() or member.isdir()):
                    raise RuntimeError('Release contains an unsafe archive entry.')
            tar.extractall(directory)
        source = Path(directory) / f'inference-stack-{version}'
        if not (source / 'charts/inference-stack/Chart.yaml').is_file():
            raise RuntimeError('Release is missing the Inference Stack chart.')
        shutil.move(str(source), ROOT)


K3S_VERSION = 'v1.37.2+k3s1'
K3S_SHA256 = '265b3ee6a3198ef14033c63ef46cbb32370d83795199fb6d1b01f21575eddbda'
HELM_VERSION = 'v3.19.0'
HELM_SHA256 = 'a7f81ce08007091b86d8bd696eb4d86b8d0f2e1b9f6c714be62f82f96a594496'


def checked_download(url, digest):
    data = download(url)
    if hashlib.sha256(data).hexdigest() != digest:
        raise RuntimeError('Dependency checksum did not match.')
    return data


def metadata(field):
    request = urllib.request.Request('http://169.254.169.254/latest/api/token', method='PUT',
                                     headers={'X-aws-ec2-metadata-token-ttl-seconds': '60'})
    with urllib.request.urlopen(request, timeout=5) as response:
        token = [REDACTED]
    request = urllib.request.Request('http://169.254.169.254/latest/meta-data/' + field,
                                     headers={'X-aws-ec2-metadata-token': token})
    with urllib.request.urlopen(request, timeout=5) as response:
        return response.read().decode()


def install_k3s(config, worker=False):
    binary = Path('/usr/local/bin/k3s')
    if not binary.exists():
        binary.write_bytes(checked_download(f'https://github.com/k3s-io/k3s/releases/download/{K3S_VERSION}/k3s', K3S_SHA256))
        binary.chmod(0o755)
    write('/etc/rancher/k3s/config.yaml', json.dumps(config))
    mode = 'agent' if worker else 'server'
    write('/etc/systemd/system/k3s.service', f"""[Unit]
Description=Inference Stack Kubernetes
After=network-online.target
Wants=network-online.target
[Service]
Type=notify
ExecStart=/usr/local/bin/k3s {mode}
KillMode=process
Delegate=yes
LimitNOFILE=1048576
LimitNPROC=infinity
TasksMax=infinity
TimeoutStartSec=0
Restart=always
RestartSec=5
[Install]
WantedBy=multi-user.target
""", 0o644)
    run('systemctl', 'daemon-reload')
    run('systemctl', 'enable', '--now', 'k3s')


def install_helm():
    if not Path('/usr/local/bin/helm').exists():
        import io
        data = checked_download(f'https://get.helm.sh/helm-{HELM_VERSION}-linux-amd64.tar.gz', HELM_SHA256)
        with tarfile.open(fileobj=io.BytesIO(data)) as archive:
            content = archive.extractfile('linux-amd64/helm').read()
        path = Path('/usr/local/bin/helm')
        path.write_bytes(content)
        path.chmod(0o755)


def kubectl(*args):
    return run('/usr/local/bin/k3s', 'kubectl', *args)


def proxy_config(host, launcher, litellm, grafana):
    return f"""map $http_upgrade $connection_upgrade {{ default upgrade; '' close; }}
server {{
    listen 80 default_server;
    server_name _;
    server_tokens off;
    absolute_redirect off;
    client_max_body_size 20m;
    proxy_http_version 1.1;
    proxy_set_header Host {host};
    proxy_set_header X-Forwarded-Proto https;
    proxy_set_header X-Forwarded-For $remote_addr;
    proxy_set_header Upgrade $http_upgrade;
    proxy_set_header Connection $connection_upgrade;
    proxy_buffering off;
    proxy_read_timeout 120s;
    location = /litellm {{ return 302 /litellm/ui; }}
    location /litellm/ {{ proxy_pass http://{litellm}:4000; }}
    location = /grafana {{ return 302 /grafana/; }}
    location /grafana/ {{ proxy_pass http://{grafana}:80; }}
    location / {{ proxy_pass http://{launcher}:8080; }}
}}
"""


def chart_values(public_url, password, credentials):
    if len(password) < 20 or len(set(password)) < 5 or not re.fullmatch(r'[A-Za-z0-9_@%+=:,./!?~-]+', password):
        raise RuntimeError('Choose a password with at least 20 characters and five distinct characters.')
    if not re.fullmatch(r'https://[a-z0-9-]+\.cloudfront\.net', public_url):
        raise RuntimeError('The HTTPS address is not a CloudFront hostname.')
    control = {'inference-stack/role': 'control'}
    return {
        'launcher': {'nodeSelector': control, 'adminSecret': '[REDACTED]',
                     'awsCapacity': True, 'litellmPublicUrl': public_url + '/litellm', 'grafanaPublicUrl': public_url + '/grafana'},
        'litellm': {
            'nodeSelector': control, 'masterkey': credentials['masterkey'],
            'resources': {'requests': {'cpu': '500m', 'memory': '4Gi'}, 'limits': {'memory': '5Gi'}},
            'envVars': {'SERVER_ROOT_PATH': '/litellm', 'PROXY_BASE_URL': public_url + '/litellm', 'UI_USERNAME': 'admin', 'FORWARDED_ALLOW_IPS': '*'},
            'extraEnvVars': [{'name': 'UI_PASSWORD', 'valueFrom': {'secretKeyRef': {'name': 'inference-stack-admin', 'key': 'password'}}}],
            'postgresql': {'primary': {'nodeSelector': control}, 'auth': {
                'password': [REDACTED]'database'], 'postgres-password': [REDACTED]'database']}},
        },
        'prometheus': {'server': {'nodeSelector': control, 'retention': '1d'}},
        'grafana': {'nodeSelector': control, 'admin': {'existingSecret': '[REDACTED]', 'userKey': 'username', 'passwordKey': 'password'},
                    'grafana.ini': {'auth.anonymous': {'enabled': False}, 'server': {
                        'root_url': public_url + '/grafana/', 'serve_from_sub_path': True}}},
    }


def configure_stack(public_url, password):
    path = Path('/etc/inference-stack/credentials.json')
    if not path.exists():
        write(path, json.dumps({'masterkey': 'sk-' + secrets.token_hex(24), 'database': secrets.token_hex(24), 'password': password}))
    credentials = json.loads(path.read_text())
    if credentials['password'] != password:
        raise RuntimeError('The installation password changed. Restore the original password before retrying.')
    values = chart_values(public_url, password, credentials)
    # Apply secret via stdin: never pass the password in a command line.
    namespace = {'apiVersion': 'v1', 'kind': 'Namespace', 'metadata': {'name': 'inference'}}
    secret = {'apiVersion': 'v1', 'kind': 'Secret', 'metadata': {'name': 'inference-stack-admin', 'namespace': 'inference'},
              'stringData': {'username': 'admin', 'password': password}}
    for resource in (namespace, secret):
        result = subprocess.run(['/usr/local/bin/k3s', 'kubectl', 'apply', '-f', '-'], input=json.dumps(resource), capture_output=True, text=True)
        if result.returncode:
            raise RuntimeError('Could not configure the installation credentials.')
    write('/etc/inference-stack/values.json', json.dumps(values))
    run('/usr/local/bin/helm', 'upgrade', '--install', 'inference-stack', str(ROOT / 'charts/inference-stack'),
        '-n', 'inference', '-f', '/etc/inference-stack/values.json', '--wait', '--timeout', '20m')
    addresses = []
    for name in ('inference-stack-launcher', 'inference-stack-litellm', 'inference-stack-grafana'):
        addresses.append(json.loads(kubectl('get', 'service', name, '-n', 'inference', '-o', 'json'))['spec']['clusterIP'])
    write('/etc/nginx/sites-available/inference-stack', proxy_config(public_url.removeprefix('https://'), *addresses), 0o644)
    Path('/etc/nginx/sites-enabled/default').unlink(missing_ok=True)
    link = Path('/etc/nginx/sites-enabled/inference-stack')
    if not link.exists():
        link.symlink_to('/etc/nginx/sites-available/inference-stack')
    run('nginx', '-t')
    run('systemctl', 'enable', '--now', 'nginx')
    run('systemctl', 'reload', 'nginx')
    return addresses[0]


def configure_capacity(stack):
    region = os.environ['AWS_DEFAULT_REGION']
    config = {key: os.environ[name] for key, name in (
        ('schedule', 'GPU_SCHEDULE'), ('stop_role', 'GPU_STOP_ROLE'), ('stop_function', 'GPU_STOP_FUNCTION'),
        ('template', 'GPU_TEMPLATE'), ('template_version', 'GPU_TEMPLATE_VERSION'), ('subnet', 'GPU_SUBNET'), ('zone', 'GPU_ZONE'))}
    config['groups'] = os.environ['GPU_GROUPS'].split(',')
    config['region'] = region
    config['hours'] = int(os.environ['STOP_AFTER_HOURS'])
    write('/etc/inference-stack/capacity.json', json.dumps(config))
    console = f'https://{region}.console.aws.amazon.com'
    info = {'provider': 'aws', 'instance_type': 't3.large', 'region': region, 'hourly_usd': 0.0832,
            'delete_url': f'{console}/cloudformation/home?region={region}#/stacks/stackinfo?stackId={quote(stack, safe="")}' }
    write('/etc/inference-stack/public/info.json', json.dumps(info), 0o644)
    write('/etc/systemd/system/inference-stack-capacity.service', f"""[Unit]
Description=Inference Stack GPU capacity
After=k3s.service network-online.target
Requires=k3s.service
[Service]
ExecStart=/usr/bin/python3 {ROOT}/aws/capacity.py
Environment=AWS_DEFAULT_REGION={region}
RuntimeDirectory=inference-stack
RuntimeDirectoryMode=0700
RuntimeDirectoryPreserve=yes
Restart=always
RestartSec=5
[Install]
WantedBy=multi-user.target
""", 0o644)
    run('systemctl', 'daemon-reload')
    run('systemctl', 'enable', '--now', 'inference-stack-capacity')


def distribution_url(stack):
    deadline = time.monotonic() + 1800
    while time.monotonic() < deadline:
        try:
            resource = aws('cloudformation', 'describe-stack-resource', '--stack-name', stack, '--logical-resource-id', 'Distribution')
            distribution = resource['StackResourceDetail']['PhysicalResourceId']
            domain = aws('cloudfront', 'get-distribution', '--id', distribution)['Distribution']['DomainName']
            return f'https://{domain}'
        except (KeyError, RuntimeError):
            time.sleep(10)
    raise RuntimeError('The HTTPS address was not created. Check CloudFormation events.')


def request(address, password):
    headers = {'Authorization': 'Basic ' + base64.b64encode(f'admin:{password}'.encode()).decode()}
    with urllib.request.urlopen(urllib.request.Request(f'http://{address}:8080/api/status', headers=headers), timeout=30) as response:
        return json.load(response)


def wait_for_services(address, password):
    deadline = time.monotonic() + 600
    while time.monotonic() < deadline:
        try:
            status = request(address, password)
            if all(status['components'][key]['healthy'] for key in ('litellm', 'router', 'grafana')) and not status.get('capacity', {}).get('error'):
                return
        except (urllib.error.URLError, TimeoutError):
            pass
        time.sleep(5)
    raise RuntimeError('The stack services did not become ready. Check the installation services.')


def install_worker():
    memory = int(run('nvidia-smi', '--query-gpu=memory.total', '--format=csv,noheader,nounits').strip().splitlines()[0])
    product = run('nvidia-smi', '--query-gpu=name', '--format=csv,noheader').strip().splitlines()[0]
    product = re.sub(r'[^A-Za-z0-9_.-]+', '-', product).strip('-')[:63]
    join = json.loads(aws('secretsmanager', 'get-secret-value', '--secret-id', os.environ['JOIN_SECRET'])['SecretString'])
    run('apt-get', 'update', '-qq')
    run('apt-get', 'install', '-y', 'conntrack', 'socat', 'iptables')
    install_k3s({'server': join['server'], 'token': join['token'], 'node-name': metadata('instance-id'),
                 'node-label': ['inference-stack/role=gpu', f'nvidia.com/gpu.product={product}', f'nvidia.com/gpu.memory={memory}',
                                f'node.kubernetes.io/instance-type={metadata("instance-type")}'],
                 'default-runtime': 'nvidia'}, worker=True)


def main():
    stage = 'Starting installation'
    stack = os.environ['STACK_ID']
    try:
        stage = 'Installing prerequisites'
        print(stage, flush=True)
        run('apt-get', 'update', '-qq')
        run('apt-get', 'install', '-y', 'nginx', 'conntrack', 'socat', 'iptables')
        stage = 'Downloading Inference Stack'
        print(stage, flush=True)
        install_bundle(os.environ['STACK_VERSION'])
        install_helm()
        stage = 'Starting Kubernetes'
        print(stage, flush=True)
        config_path = Path('/etc/rancher/k3s/config.yaml')
        config = json.loads(config_path.read_text()) if config_path.exists() else {
            'agent-token': [REDACTED], 'node-label': ['inference-stack/role=control'],
            'disable': ['traefik', 'servicelb', 'metrics-server'], 'write-kubeconfig-mode': '600'}
        install_k3s(config)
        os.environ['KUBECONFIG'] = '/etc/rancher/k3s/k3s.yaml'
        token = Path('/var/lib/rancher/k3s/server/agent-token').read_text().strip()
        join = {'server': f'https://{metadata("local-ipv4")}:6443', 'token': token}
        join_path = Path('/etc/inference-stack/join.json')
        write(join_path, json.dumps(join))
        aws('secretsmanager', 'put-secret-value', '--secret-id', os.environ['JOIN_SECRET'], '--secret-string', f'file://{join_path}')
        join_path.unlink()
        run('/usr/local/bin/helm', 'repo', 'add', 'nvdp', 'https://nvidia.github.io/k8s-device-plugin')
        run('/usr/local/bin/helm', 'upgrade', '--install', 'nvidia-device-plugin', 'nvdp/nvidia-device-plugin',
            '--version', '0.20.2', '-n', 'kube-system', '--set-json', 'nodeSelector={"inference-stack/role":"gpu"}')
        configure_capacity(stack)
        stage = 'Creating the HTTPS address'
        print(stage, flush=True)
        public_url = distribution_url(stack)
        password = aws('secretsmanager', 'get-secret-value', '--secret-id', os.environ['PASSWORD_SECRET'])['SecretString']
        stage = 'Starting Inference Stack'
        print(stage, flush=True)
        address = configure_stack(public_url, password)
        stage = 'Checking stack services'
        print(stage, flush=True)
        wait_for_services(address, password)
        run('aws', 'cloudformation', 'signal-resource', '--stack-name', stack, '--logical-resource-id', 'Ready', '--unique-id', 'installer', '--status', 'SUCCESS')
        print('Inference Stack is ready. No GPUs or models were installed.', flush=True)
    except Exception:
        print(f'{stage} failed. Inspect this machine through AWS Systems Manager.', flush=True)
        run('aws', 'cloudformation', 'signal-resource', '--stack-name', stack, '--logical-resource-id', 'Ready', '--unique-id', 'installer', '--status', 'FAILURE')
        raise SystemExit(1) from None


if __name__ == '__main__':
    import sys
    if sys.argv[1:] == ['--worker']:
        try:
            install_worker()
        except Exception:
            print('GPU setup failed. Inspect this worker through AWS Systems Manager.', flush=True)
            raise SystemExit(1) from None
    else:
        main()

import httpx

import settings

client = httpx.Client(
    base_url=settings.LITELLM_URL,
    headers={"Authorization": f"Bearer {settings.LITELLM_MASTER_KEY}"},
    timeout=120,
)


def list_models() -> list[dict]:
    rows = client.get("/model/info", timeout=5).raise_for_status().json()["data"]
    return [
        {
            "name": row["model_name"],
            "id": row["model_info"]["id"],
            "served_model": row["litellm_params"]["model"].removeprefix("hosted_vllm/"),
            "api_base": row["litellm_params"].get("api_base", ""),
        }
        for row in rows
    ]


def register_model(name: str, served_model: str, api_base: str) -> None:
    remove_model(name)
    client.post(
        "/model/new",
        json={
            "model_name": name,
            "litellm_params": {"model": f"hosted_vllm/{served_model}", "api_base": api_base},
        },
    ).raise_for_status()


def remove_model(name: str) -> None:
    for model in list_models():
        if model["name"] == name:
            client.post("/model/delete", json={"id": model["id"]}).raise_for_status()

#!/usr/bin/env python3
"""Manage this stack's GPU machines. Only the launcher can reach this Unix socket."""

import datetime as dt
from http.server import BaseHTTPRequestHandler
import json
import os
from pathlib import Path
import socketserver
import subprocess

import gpus

CONFIG = Path('/etc/inference-stack/capacity.json')
SOCKET = '/run/inference-stack/capacity.sock'


class CapacityError(Exception):
    pass


def run(*args, json_output=True):
    result = subprocess.run(args, capture_output=True, text=True, timeout=30)
    if result.returncode:
        raise CapacityError('Could not update AWS capacity. Check the installation in AWS, then retry.')
    return json.loads(result.stdout) if json_output and result.stdout.strip() else {}


def aws(service, action, **kwargs):
    args = ['aws', service, action, '--output', 'json']
    for key, value in kwargs.items():
        if isinstance(value, bool):
            args.append('--' + ('' if value else 'no-') + key.replace('_', '-'))
            continue
        args += ['--' + key.replace('_', '-'), value if isinstance(value, str) else json.dumps(value)]
    return run(*args)


def kubectl(*args):
    output = args[0] == 'get'
    return run('/usr/local/bin/k3s', 'kubectl', *args, *(['-o', 'json'] if output else []), json_output=output)


def now():
    return dt.datetime.now(dt.timezone.utc).replace(microsecond=0)


def groups(config):
    rows = aws('autoscaling', 'describe-auto-scaling-groups', auto_scaling_group_names=config['groups'])['AutoScalingGroups']
    if {row['AutoScalingGroupName'] for row in rows} != set(config['groups']):
        raise CapacityError('A GPU group is missing. Check this installation in AWS.')
    return rows


def selected_gpu(config, current, instance_type, hourly_usd):
    rows = gpus.options(aws, config, current)['options']
    selected = next((row for row in rows if row['instance_type'] == instance_type), None)
    if selected is None:
        raise CapacityError('Choose a GPU offered in this installation’s availability zone.')
    if selected['blocker']:
        raise CapacityError(selected['blocker'] + ' No GPU was added.')
    if type(hourly_usd) not in (float, int) or hourly_usd != selected['hourly_usd']:
        raise CapacityError('The GPU price changed. Refresh and review its price before launching.')
    return selected


def deadline(config):
    schedule = aws('scheduler', 'get-schedule', name=config['schedule'])
    if schedule['State'] != 'ENABLED':
        return None
    return dt.datetime.fromisoformat(schedule['ScheduleExpression'][3:-1]).replace(tzinfo=dt.timezone.utc)


def gpu_nodes():
    return kubectl('get', 'nodes', '-l', 'inference-stack/role=gpu')['items']


def workloads(node):
    pods = kubectl('get', 'pods', '--all-namespaces', '--field-selector', f'spec.nodeName={node}')['items']
    return [p for p in pods if p.get('status', {}).get('phase') not in ('Succeeded', 'Failed')
            and not any(o['kind'] == 'DaemonSet' for o in p['metadata'].get('ownerReferences', []))]


def status(config):
    current = groups(config)
    nodes = {n['metadata']['name']: n for n in gpu_nodes()}
    pods = kubectl('get', 'pods', '--all-namespaces')['items']
    members = {i['InstanceId'] for row in current for i in row['Instances']}
    for name, node in nodes.items():
        ready = any(c['type'] == 'Ready' and c['status'] == 'True' for c in node.get('status', {}).get('conditions', []))
        if name not in members and not ready:
            kubectl('delete', 'node', name, '--ignore-not-found')
    machines = []
    specs = {}
    if any(row['Instances'] or row['DesiredCapacity'] for row in current):
        try:
            specs = {row['instance_type']: row for row in gpus.catalogue(aws, config['region'], config['zone'])}
        except CapacityError:
            pass  # Keep removal available if the catalogue or price API is down.
    for item in [item for row in current for item in row['Instances']]:
        # Worker names are their instance IDs; no address is exposed to the browser.
        node = nodes.get(item['InstanceId'], {})
        ready = any(c['type'] == 'Ready' and c['status'] == 'True' for c in node.get('status', {}).get('conditions', []))
        ready = ready and int(node.get('status', {}).get('allocatable', {}).get('nvidia.com/gpu', 0)) > 0
        state = 'removing' if item['LifecycleState'].startswith('Terminating') else 'ready' if ready else 'starting'
        models = sorted({p['metadata']['labels']['model'] for p in pods
                         if p.get('spec', {}).get('nodeName') == item['InstanceId']
                         and p.get('status', {}).get('phase') not in ('Succeeded', 'Failed')
                         and p['metadata'].get('labels', {}).get('model')})
        machines.append({**specs.get(item['InstanceType'], {'instance_type': item['InstanceType'], 'name': item['InstanceType'], 'memory_gb': None, 'gpu_count': None, 'hourly_usd': None}), 'id': item['InstanceId'], 'state': state, 'models': models})
    stop = deadline(config)
    error = ''
    pending = 0
    for row in current:
        if row['DesiredCapacity'] and not row['Instances']:
            instance_type = gpus.group_type(row)
            machines.append({**specs.get(instance_type, {'instance_type': instance_type, 'name': instance_type}),
                             'id': 'pending-' + str(config['groups'].index(row['AutoScalingGroupName'])),
                             'state': 'starting', 'models': []})
        if row['DesiredCapacity'] > sum(item.get('LifecycleState') == 'InService' and any(m['id'] == item['InstanceId'] and m['state'] == 'ready' for m in machines) for item in row['Instances']):
            pending += 1
            activities = aws('autoscaling', 'describe-scaling-activities', auto_scaling_group_name=row['AutoScalingGroupName'], max_records=1)['Activities']
            if activities and activities[0]['StatusCode'] in ('Failed', 'Cancelled'):
                error = 'AWS could not start a selected GPU. Check quota and capacity in AWS, or cancel the pending machine and choose another type.'
    return {'desired': sum(row['DesiredCapacity'] for row in current), 'limit': len(current), 'machines': machines,
            'pending': pending, 'stop_at': stop.isoformat() if stop else None, 'error': error,
            'hours': config['hours'], 'region': config['region']}


def set_deadline(config, stop):
    aws('scheduler', 'update-schedule', name=config['schedule'], state='ENABLED',
        schedule_expression=f'at({stop.strftime("%Y-%m-%dT%H:%M:%S")})', schedule_expression_timezone='UTC',
        flexible_time_window={'Mode': 'OFF'}, target={
            'Arn': config['stop_function'],
            'RoleArn': config['stop_role'],
            'Input': '{}',
            'RetryPolicy': {'MaximumEventAgeInSeconds': 3600, 'MaximumRetryAttempts': 3}})


def resize(config, expected, target, instance_type=None, hourly_usd=None):
    current = groups(config)
    desired = sum(row['DesiredCapacity'] for row in current)
    if type(expected) is not int or expected != desired:
        raise CapacityError('GPU capacity changed. Refresh and try again.')
    if type(target) is not int or not 0 <= target <= len(current):
        raise CapacityError('Choose a machine count within this installation’s limit.')
    if target == expected + 1:
        selected_gpu(config, current, instance_type, hourly_usd)
        available = next((row for row in current if row['DesiredCapacity'] == 0 and not row['Instances']), None)
        if available is None:
            raise CapacityError('Wait for a removed GPU to finish shutting down, then retry.')
        stop = deadline(config)
        if expected and (not stop or stop <= now() + dt.timedelta(minutes=2)):
            raise CapacityError('This GPU session is ending. Remove the GPUs before starting another session.')
        if not expected:
            if any(row['Instances'] for row in current):
                raise CapacityError('Wait for the previous GPUs to finish shutting down, then retry.')
            stop = now() + dt.timedelta(hours=config['hours'])
        # Schedule first: never create billable capacity without its independent deadline.
        set_deadline(config, stop)
        # Each CloudFormation-owned group contains one machine. Changing an empty
        # group cannot change the type or replacement cost of an existing GPU.
        aws('autoscaling', 'update-auto-scaling-group', auto_scaling_group_name=available['AutoScalingGroupName'],
            min_size=0, max_size=1, vpc_zone_identifier=config['subnet'], mixed_instances_policy={
                'LaunchTemplate': {'LaunchTemplateSpecification': {'LaunchTemplateId': config['template'], 'Version': config['template_version']},
                                   'Overrides': [{'InstanceType': instance_type}]},
                'InstancesDistribution': {'OnDemandPercentageAboveBaseCapacity': 100}})
        aws('autoscaling', 'set-desired-capacity', auto_scaling_group_name=available['AutoScalingGroupName'], desired_capacity=1)
        return {'status': 'accepted', 'instance_type': instance_type}
    if target != 0:
        raise CapacityError('Add one machine at a time, or remove a specific GPU.')
    members = {i['InstanceId'] for row in current for i in row['Instances']}
    if any(n['metadata']['name'] in members for n in gpu_nodes()):
        raise CapacityError('Remove each GPU before cancelling the remaining pending capacity.')
    for row in current:
        if row['DesiredCapacity']:
            aws('autoscaling', 'set-desired-capacity', auto_scaling_group_name=row['AutoScalingGroupName'], desired_capacity=0)


def remove(config, instance):
    current = groups(config)
    if isinstance(instance, str) and instance.startswith('pending-'):
        slot = int(instance.removeprefix('pending-'))
        if not 0 <= slot < len(config['groups']):
            raise CapacityError('Unknown GPU machine.')
        row = next(row for row in current if row['AutoScalingGroupName'] == config['groups'][slot])
        if row['Instances']:
            raise CapacityError('This machine has started. Refresh and remove it from GPUs.')
        if row['DesiredCapacity']:
            aws('autoscaling', 'set-desired-capacity', auto_scaling_group_name=row['AutoScalingGroupName'], desired_capacity=0)
        return
    item = next((i for row in current for i in row['Instances'] if i['InstanceId'] == instance), None)
    if item is None or item['LifecycleState'].startswith('Terminating'):
        return  # A retry must not remove a different GPU.
    node = next((n for n in gpu_nodes() if n['metadata']['name'] == instance), None)
    if node:
        kubectl('cordon', instance)
    try:
        if node and workloads(instance):
            raise CapacityError('This GPU is in use. Remove its models before removing the GPU.')
        aws('autoscaling', 'terminate-instance-in-auto-scaling-group', instance_id=instance,
            should_decrement_desired_capacity=True)
    except Exception:
        if node and not node.get('spec', {}).get('unschedulable'):
            kubectl('uncordon', instance)
        raise
    if node:
        kubectl('delete', 'node', instance, '--ignore-not-found')


class Handler(BaseHTTPRequestHandler):
    def log_message(self, *args):
        pass

    def respond(self, code, body):
        data = json.dumps(body).encode()
        self.send_response(code)
        self.send_header('Content-Type', 'application/json')
        self.send_header('Content-Length', str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    def handle_request(self):
        try:
            config = json.loads(CONFIG.read_text())
            if self.command == 'GET' and self.path == '/':
                return self.respond(200, status(config))
            if self.command == 'GET' and self.path == '/options':
                return self.respond(200, gpus.options(aws, config, groups(config)))
            length = int(self.headers.get('Content-Length', '0'))
            if not 0 < length <= 1024:
                return self.respond(400, {'detail': 'Invalid capacity request.'})
            body = json.loads(self.rfile.read(length))
            if self.command == 'POST' and self.path == '/':
                resize(config, body.get('expected'), body.get('desired'), body.get('instance_type'), body.get('hourly_usd'))
            elif self.command == 'POST' and self.path == '/remove':
                remove(config, body.get('id'))
            else:
                return self.respond(404, {'detail': 'Unknown capacity action.'})
            self.respond(200, {'status': 'accepted'})
        except CapacityError as error:
            self.respond(409, {'detail': str(error)})
        except Exception:
            self.respond(503, {'detail': 'Could not check GPU capacity. Refresh or check the installation in AWS.'})

    do_GET = handle_request
    do_POST = handle_request


if __name__ == '__main__':
    os.umask(0o077)
    Path(SOCKET).parent.mkdir(parents=True, exist_ok=True)
    Path(SOCKET).unlink(missing_ok=True)
    # A single worker serializes changes, including double clicks and concurrent tabs.
    with socketserver.UnixStreamServer(SOCKET, Handler) as server:
        server.serve_forever()

"""Operate this installation's namespace using its service account and Helm."""

import json
import os
import shlex
import ssl
import subprocess
import time
from functools import lru_cache
from pathlib import Path

import httpx
import yaml

import litellm_client
import settings

SERVICE_ACCOUNT = Path("/var/run/secrets/kubernetes.io/serviceaccount")


def api(method: str, path: str, raw=False, **kwargs):
    context = ssl.create_default_context(cafile=str(SERVICE_ACCOUNT / "ca.crt"))
    # Read the projected token for each request so rotation works.
    token = [REDACTED] / "token").read_text().strip()
    host = os.environ["KUBERNETES_SERVICE_HOST"]
    port = os.environ.get("KUBERNETES_SERVICE_PORT", "443")
    with httpx.Client(base_url=f"https://{host}:{port}", verify=context, timeout=10,
                      headers={"Authorization": f"Bearer {token}"}) as client:
        response = client.request(method, path, **kwargs).raise_for_status()
        return response.text if raw else response.json()


def resource_path(resource: str, group: str = "") -> str:
    prefix = f"/apis/{group}/v1" if group else "/api/v1"
    return f"{prefix}/namespaces/{settings.HELM_NAMESPACE}/{resource}"


@lru_cache(maxsize=2)
def capabilities(bucket: int) -> dict:
    try:
        result = api("POST", "/apis/authorization.k8s.io/v1/selfsubjectrulesreviews", json={
            "apiVersion": "authorization.k8s.io/v1", "kind": "SelfSubjectRulesReview",
            "spec": {"namespace": settings.HELM_NAMESPACE}})
        rules = result.get("status", {}).get("resourceRules", [])
        def permits(verb, resource, group=""):
            return any(not rule.get("resourceNames") and
                       (verb in rule["verbs"] or "*" in rule["verbs"]) and
                       (group in rule["apiGroups"] or "*" in rule["apiGroups"]) and
                       (resource in rule["resources"] or "*" in rule["resources"]) for rule in rules)
        read = permits("list", "deployments", "apps")
        resources = [("deployments", "apps"), ("jobs", "batch"), ("secrets", ""),
                     ("services", ""), ("configmaps", ""), ("serviceaccounts", ""),
                     ("roles", "rbac.authorization.k8s.io"), ("rolebindings", "rbac.authorization.k8s.io")]
        direct = read and all(permits(verb, resource, group) for resource, group in resources
                              for verb in ("get", "list", "watch", "create", "update", "patch", "delete"))
        direct = direct and all(permits(verb, "pods") for verb in ("get", "list", "watch"))
        return {"read": read, "deploy": direct, "error": ""}
    except Exception:
        return {"read": False, "deploy": False, "error": "Could not check Kubernetes permissions. You can still generate a deployment command."}


def permissions() -> dict:
    return capabilities(int(time.monotonic() // 60))


def gpu_inventory(exclude_model: str = "") -> dict:
    try:
        nodes = api("GET", "/api/v1/nodes")["items"]
        pods = api("GET", "/api/v1/pods")["items"]
        occupied = {}
        for pod in pods:
            if pod.get("status", {}).get("phase") in ("Succeeded", "Failed"):
                continue
            if exclude_model and pod.get("metadata", {}).get("namespace") == settings.HELM_NAMESPACE and pod.get("metadata", {}).get("labels", {}).get("model") == exclude_model:
                continue
            spec = pod["spec"]
            def gpu(container):
                resources = container.get("resources", {})
                return int(resources.get("requests", resources.get("limits", {})).get("nvidia.com/gpu", 0))
            count = max(sum(gpu(c) for c in spec.get("containers", [])),
                        max((gpu(c) for c in spec.get("initContainers", [])), default=0))
            node = spec.get("nodeName")
            occupied[node] = occupied.get(node, 0) + count
        devices = []
        for node in nodes:
            if node.get("spec", {}).get("unschedulable"):
                continue
            if not any(c["type"] == "Ready" and c["status"] == "True" for c in node["status"].get("conditions", [])):
                continue
            if any(t.get("effect") in ("NoSchedule", "NoExecute") and t.get("key") != "nvidia.com/gpu" for t in node.get("spec", {}).get("taints", [])):
                continue
            count = int(node["status"].get("allocatable", {}).get("nvidia.com/gpu", 0))
            if not count:
                continue
            labels = node["metadata"].get("labels", {})
            memory = labels.get("nvidia.com/gpu.memory")
            devices.append({"name": labels.get("nvidia.com/gpu.product", "NVIDIA GPU"), "count": count,
                            "instance_type": labels.get("node.kubernetes.io/instance-type", ""),
                            "available": max(0, count - occupied.get(node["metadata"]["name"], 0)),
                            "memory_gb": round(float(memory) / 1024, 1) if memory else None})
        return {"count": sum(d["count"] for d in devices), "devices": devices, "error": ""}
    except Exception:
        return {"count": None, "devices": [], "error": "GPU capacity is unknown. Node and pod read access is needed to check allocation."}


def legacy_model(row: dict, registered: list[dict]) -> dict | None:
    """Recognize old chart releases through this stack's LiteLLM registration."""
    metadata = row["metadata"]
    annotations = metadata.get("annotations", {})
    name = annotations.get("meta.helm.sh/release-name")
    if (not name or metadata["name"] != f"{name}-vllm"
            or metadata.get("labels", {}).get("app.kubernetes.io/managed-by") != "Helm"
            or annotations.get("meta.helm.sh/release-namespace") != settings.HELM_NAMESPACE
            or row["spec"].get("selector", {}).get("matchLabels", {}).get("model") != name):
        return None
    container = next((c for c in row["spec"]["template"]["spec"]["containers"] if c["name"] == "vllm"), {})
    command = container.get("command", [])
    args = container.get("args", [])
    simulate = len(args) >= 2 and args[0] == "--model"
    if simulate:
        model = args[1]
    elif len(command) >= 3 and command[:2] == ["vllm", "serve"]:
        model = command[2]
    else:
        return None
    if not any(m["name"] == name and m["served_model"] == model
               and m.get("api_base") == f"http://{name}-epp:8081/v1" for m in registered):
        return None
    return {"name": name, "served_model": model, "simulate": simulate, "context": None,
            "gpus_per_replica": int(container.get("resources", {}).get("limits", {}).get("nvidia.com/gpu", 1))}


def models(registered: list[dict] | None = None) -> list[dict]:
    rows = api("GET", resource_path("deployments", "apps"))["items"]
    result = []
    by_name = {row["metadata"]["name"]: row for row in rows}
    for row in rows:
        metadata = row["metadata"]
        labels = metadata.get("labels", {})
        stack = labels.get("inference-stack/stack")
        if stack and stack != settings.HELM_STACK_RELEASE:
            continue
        annotations = metadata.get("annotations", {})
        if stack:
            model = {"name": labels["inference-stack/model"], "served_model": annotations["inference-stack/model-id"],
                     "gpus_per_replica": int(annotations.get("inference-stack/gpus", 1)),
                     "context": int(annotations.get("inference-stack/context", 4096)),
                     "simulate": annotations.get("inference-stack/simulate") == "true"}
        else:
            if not metadata["name"].endswith("-vllm"):
                continue
            if registered is None:
                try:
                    registered = litellm_client.list_models()
                except httpx.HTTPError:
                    registered = []
            model = legacy_model(row, registered)
            if not model:
                continue
        name = model["name"]
        spec = row["spec"]
        router = by_name.get(f"{name}-epp", {})
        observed = row.get("status", {}).get("observedGeneration", 0) >= metadata.get("generation", 1)
        ready = row.get("status", {}).get("readyReplicas", 0) if observed else 0
        result.append({**model,
                       "replicas": spec.get("replicas", 1), "ready": ready,
                       "router_ready": router.get("status", {}).get("readyReplicas", 0) > 0})
    return result


def values(request, name: str) -> dict:
    return {"model": request.model, "replicas": request.replicas, "gpusPerReplica": request.gpus_per_replica,
            "maxModelLen": request.context, "simulate": request.simulate,
            "minGpuMemoryMiB": request.min_gpu_memory_mib,
            "nodeSelector": {"node.kubernetes.io/instance-type": request.instance_type} if request.add_gpu else {},
            "huggingFaceSecret": [REDACTED], "stackRelease": settings.HELM_STACK_RELEASE,
            "llm-d-router-standalone": {"router": {"modelServers": {"matchLabels": {"model": name}},
                                                    "proxy": {"presets": {"envoy": {"configMap": {"name": f"{name}-envoy"}}}}}}}


def command(request, name: str) -> str:
    args = ["helm", "upgrade", "--install", name, settings.HELM_MODEL_CHART,
            "--namespace", settings.HELM_NAMESPACE, "--reuse-values", "--wait", "--timeout", "60m"]
    for key, value in values(request, name).items():
        args += ["--set-json", f"{key}={json.dumps(value, separators=(',', ':'))}"]
    return f"helm dependency build {shlex.quote(settings.HELM_MODEL_CHART)}\n" + shlex.join(args)


def helm(args: list[str], values_input: dict | None = None) -> str:
    result = subprocess.run(["helm", *args, "--namespace", settings.HELM_NAMESPACE],
                            input=json.dumps(values_input) if values_input is not None else None,
                            capture_output=True, text=True, timeout=3700)
    if result.returncode:
        # Helm errors may contain rendered Secrets or infrastructure details.
        raise RuntimeError("Helm could not finish. Check the release and pod events in this namespace, then retry.")
    return result.stdout


def deploy(request, name: str) -> None:
    helm(["upgrade", "--install", name, settings.BUNDLED_MODEL_CHART, "--reuse-values", "--values", "-",
          "--wait", "--timeout", "60m", "--history-max", "5"], values(request, name))


def remove(name: str) -> None:
    helm(["uninstall", name, "--ignore-not-found", "--wait", "--timeout", "5m"])


def routing_config(name: str) -> dict:
    row = api("GET", resource_path(f"configmaps/{name}-epp"))
    return yaml.safe_load(row["data"]["default-plugins.yaml"])


def save_routing(name: str, config: dict) -> None:
    # Merge into saved Helm values, preserving the rest of the routing policy.
    helm(["upgrade", name, settings.BUNDLED_MODEL_CHART, "--reuse-values", "--values", "-",
          "--wait", "--timeout", "5m", "--history-max", "5"],
         {"llm-d-router-standalone": {"router": {"epp": {"pluginsConfig": config}}}})
